def handle(app, svc):
    resp = svc.apply(app)
    decision = resp.get("decision")
    limit = resp.get("limit", 0) or 0

    # Network referral rule: self_employed with requested_limit > 4000
    # must go to manual review instead of being issued (a decline stays a decline).
    if app.get("employment") == "self_employed" and app.get("requested_limit", 0) > 4000:
        if decision == "approve":
            return {"action": "queue_review", "limit": 0}
        # decline or refer -> not issued
        return {"action": "queue_review" if decision == "refer" else "decline", "limit": 0}

    if decision == "approve":
        return {"action": "issue", "limit": limit}
    if decision == "refer":
        return {"action": "queue_review", "limit": 0}
    return {"action": "decline", "limit": 0}
